import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    static class Point {
        long x, y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long dot(Point a, Point b) {
        return a.x * b.x + a.y * b.y;
    }

    static long cross(Point a, Point b) {
        return a.x * b.y - a.y * b.x;
    }

    static Point sub(Point a, Point b) {
        return new Point(a.x - b.x, a.y - b.y);
    }

    static long distSq(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        Point[] p = new Point[8];

        for (int i = 1; i <= 7; i++) {
            String line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) break;
            StringTokenizer tokenizer = new StringTokenizer(line);
            long x = Long.parseLong(tokenizer.nextToken());
            long y = Long.parseLong(tokenizer.nextToken());
            p[i] = new Point(x, y);
        }

        boolean isValid = true;

        // 1. O ângulo ∠P2P1P3 é agudo (vértice em P1)
        Point v1 = sub(p[2], p[1]);
        Point v2 = sub(p[3], p[1]);
        if (dot(v1, v2) <= 0) {
            isValid = false;
        }

        // 2. Os segmentos P1P2 e P1P3 têm o mesmo comprimento
        if (distSq(p[1], p[2]) != distSq(p[1], p[3])) {
            isValid = false;
        }

        // 3. Os pontos P2, P3, P4 e P5 são colineares
        Point base = sub(p[3], p[2]);
        if (cross(sub(p[4], p[2]), base) != 0 || cross(sub(p[5], p[2]), base) != 0) {
            isValid = false;
        }

        // 4. Os pontos médios dos segmentos P2P3 e P4P5 são coincidentes
        if (p[2].x + p[3].x != p[4].x + p[5].x || p[2].y + p[3].y != p[4].y + p[5].y) {
            isValid = false;
        }

        // 5. O segmento P2P3 tem comprimento maior que o segmento P4P5
        if (distSq(p[2], p[3]) <= distSq(p[4], p[5])) {
            isValid = false;
        }

        // 6. Os segmentos P4P6 e P5P7 são perpendiculares ao segmento P2P3
        Point seg46 = sub(p[6], p[4]);
        Point seg57 = sub(p[7], p[5]);
        if (dot(seg46, base) != 0 || dot(seg57, base) != 0) {
            isValid = false;
        }

        // 7. Os segmentos P4P6 e P5P7 têm o mesmo comprimento
        if (distSq(p[4], p[6]) != distSq(p[5], p[7])) {
            isValid = false;
        }

        // 8. Os pontos P1 e P6 devem estar separados pela reta que contém o segmento P2P3
        long c1 = cross(sub(p[1], p[2]), base);
        long c2 = cross(sub(p[6], p[2]), base);
        if (!((c1 > 0 && c2 < 0) || (c1 < 0 && c2 > 0))) {
            isValid = false;
        }

        if (isValid) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
